import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as t,c as r,a as o}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.0.0","description":"Initial public release of github-code-search — interactive TUI, per-repo aggregation, markdown/JSON output.","frontmatter":{"title":"What's new in v1.0.0","description":"Initial public release of github-code-search — interactive TUI, per-repo aggregation, markdown/JSON output.","date":"2025-01-01T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-0-0.md","filePath":"blog/release-v1-0-0.md"}`),i={name:"blog/release-v1-0-0.md"};function n(s,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-s-new-in-github-code-search-v1-0-0" tabindex="-1">What&#39;s new in github-code-search v1.0.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-0-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.0.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.0.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.0.0</a></p></blockquote><h2 id="the-beginning" tabindex="-1">The beginning <a class="header-anchor" href="#the-beginning" aria-label="Permalink to &quot;The beginning&quot;">​</a></h2><p><code>github-code-search</code> is an interactive CLI for searching GitHub code across an entire organisation. It wraps the <a href="https://docs.github.com/en/rest/search/search#search-code" target="_blank" rel="noreferrer">GitHub Code Search API</a> and adds a keyboard-driven TUI on top, so you can browse results, fold/unfold extracts, and select the ones you care about before printing structured output.</p><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="keyboard-driven-tui" tabindex="-1">Keyboard-driven TUI <a class="header-anchor" href="#keyboard-driven-tui" aria-label="Permalink to &quot;Keyboard-driven TUI&quot;">​</a></h3><p>Search results are loaded and displayed in an interactive terminal UI. Navigate with <kbd>↑</kbd> / <kbd>↓</kbd>, fold/unfold extracts with <kbd>→</kbd> / <kbd>←</kbd>, select results with <kbd>Space</kbd>, and confirm with <kbd>Enter</kbd>. Press <kbd>?</kbd> to show the full keyboard shortcut reference.</p><p>→ <a href="/github-code-search/v2/usage/interactive-mode.html">Interactive mode guide</a></p><h3 id="per-repository-aggregation" tabindex="-1">Per-repository aggregation <a class="header-anchor" href="#per-repository-aggregation" aria-label="Permalink to &quot;Per-repository aggregation&quot;">​</a></h3><p>All code matches for the same repository are grouped together, with per-file headings. No more scanning through a flat list of individual matches.</p><h3 id="markdown-and-json-output" tabindex="-1">Markdown and JSON output <a class="header-anchor" href="#markdown-and-json-output" aria-label="Permalink to &quot;Markdown and JSON output&quot;">​</a></h3><p>Use <code>--format markdown</code> (default) for human-readable output, or <code>--format json</code> for machine-readable output suitable for further processing.</p><p>Use <code>--output-type repo-only</code> to print only repository names (no code extracts).</p><p>→ <a href="/github-code-search/v2/usage/output-formats.html">Output formats guide</a></p><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>Exclude noisy repositories with <code>--exclude-repositories</code> or specific extracts with <code>--exclude-extracts</code>. Both flags accept short (<code>repoName</code>) and long (<code>org/repoName</code>) forms.</p><p>→ <a href="/github-code-search/v2/usage/filtering.html">Filtering guide</a></p><h3 id="team-grouping" tabindex="-1">Team grouping <a class="header-anchor" href="#team-grouping" aria-label="Permalink to &quot;Team grouping&quot;">​</a></h3><p>Group results by team prefix using <code>--group-by-team-prefix</code>. Results are arranged in sections per team, making it easy to see which squads own the code that matches your search.</p><p>→ <a href="/github-code-search/v2/usage/team-grouping.html">Team grouping guide</a></p><h3 id="non-interactive-ci-mode" tabindex="-1">Non-interactive / CI mode <a class="header-anchor" href="#non-interactive-ci-mode" aria-label="Permalink to &quot;Non-interactive / CI mode&quot;">​</a></h3><p>Use <code>--no-interactive</code> (or set <code>CI=true</code>) to pipe output directly to downstream tools. Syntax highlighting and TUI chrome are stripped so the output is clean.</p><p>→ <a href="/github-code-search/v2/usage/non-interactive-mode.html">Non-interactive mode guide</a></p><h3 id="built-in-upgrade-command" tabindex="-1">Built-in upgrade command <a class="header-anchor" href="#built-in-upgrade-command" aria-label="Permalink to &quot;Built-in upgrade command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Checks for a newer binary on GitHub Releases and replaces the running binary in-place. No package manager required.</p><p>→ <a href="/github-code-search/v2/usage/upgrade.html">Upgrade guide</a></p>',27)])])}const k=a(i,[["render",n]]);export{f as __pageData,k as default};
